import numpy as np
from collections import defaultdict

def build(agent, objs=(), prevs=()):
    X = np.zeros(500)
    for r in range(10):
        for c in range(10):
            if r in (0, 9) or c in (0, 9):
                X[(r*10+c)*5+3] = 1          # wall border
    ar, ac = agent
    X[(ar*10+ac)*5+0] = 1                    # agent
    X[(ar*10+ac)*5+4] = 1                    # prev frame: stationary agent
    for (r, c, ch) in objs:
        X[(r*10+c)*5+ch] = 1
    for (r, c) in prevs:
        X[(r*10+c)*5+4] = 1
    return X

dirs = {1: (-1, 0), 2: (1, 0), 3: (0, -1), 4: (0, 1)}   # up, down, left, right
opp  = {1: 2, 2: 1, 3: 4, 4: 3}

positions = [(r, c) for r in range(1, 9) for c in range(1, 9)]
states, meta = [], []
for (ar, ac) in positions:
    states.append(build((ar, ac)))
    meta.append(('empty', 0, (ar, ac)))
    for act, (dr, dc) in dirs.items():
        tr, tc = ar+dr, ac+dc
        if not (1 <= tr <= 8 and 1 <= tc <= 8):
            continue
        states.append(build((ar, ac), [(tr, tc, 2)])); meta.append(('reward', act, (ar, ac)))
        states.append(build((ar, ac), [(tr, tc, 3)])); meta.append(('obstacle', act, (ar, ac)))
        states.append(build((ar, ac), [(tr, tc, 1)])); meta.append(('mover_stat', act, (ar, ac)))
        pr, pc = tr+dr, tc+dc               # prev further out => moving toward agent
        if 1 <= pr <= 8 and 1 <= pc <= 8:
            states.append(build((ar, ac), [(tr, tc, 1)], [(pr, pc)]))
            meta.append(('mover_toward', act, (ar, ac)))

X = np.array(states)
print("num states", len(X))
probs = []
for i in range(0, len(X), 256):
    probs.append(forward(X[i:i+256]))
probs = np.concatenate(probs, axis=0)

def softmax(z):
    z = z - z.max(axis=1, keepdims=True)
    e = np.exp(z)
    return e / e.sum(axis=1, keepdims=True)

P = softmax(probs)

base = {}
for i, (typ, act, pos) in enumerate(meta):
    if typ == 'empty':
        base[pos] = P[i]

agg = defaultdict(list)
for i, (typ, act, pos) in enumerate(meta):
    if typ == 'empty':
        continue
    toward = P[i][act]; away = P[i][opp[act]]
    bt = base[pos][act]; ba = base[pos][opp[act]]
    agg[typ].append((toward - away) - (bt - ba))

for typ in ['reward', 'obstacle', 'mover_stat', 'mover_toward']:
    v = np.array(agg[typ])
    print(f"{typ:12s} net attraction = {v.mean():+.3f} +/- {v.std()/np.sqrt(len(v)):.3f}  (n={len(v)})")

import numpy as np

def make_state(agent=None, reward=None, obstacle=None, mover=None, mover_prev=None):
    g = np.zeros((10,10,5))
    g[0,:,3]=1; g[9,:,3]=1; g[:,0,3]=1; g[:,9,3]=1   # wall border
    if agent is not None:      g[agent[0],agent[1],0]=1
    if reward is not None:     g[reward[0],reward[1],2]=1
    if obstacle is not None:   g[obstacle[0],obstacle[1],3]=1
    if mover is not None:      g[mover[0],mover[1],1]=1
    if mover_prev is not None: g[mover_prev[0],mover_prev[1],4]=1
    return g.flatten()

positions = [(2,2),(2,6),(3,4),(4,3),(4,6),(5,4),(6,2),(6,6)]
dirs = {'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}
aidx = {'up':1,'down':2,'left':3,'right':4}
opp  = {'up':'down','down':'up','left':'right','right':'left'}

states=[]; meta=[]
for p in positions:
    states.append(make_state(agent=p)); meta.append(('base',p,'none'))
for typ, kw in [('reward','reward'),('obstacle','obstacle'),('mover_stat','mover')]:
    for p in positions:
        for d,(dr,dc) in dirs.items():
            r=(p[0]+dr,p[1]+dc)
            states.append(make_state(agent=p, **{kw:r})); meta.append((typ,p,d))
# mover approaching: current at neighbor, previous frame one cell further out (moving toward agent)
for p in positions:
    for d,(dr,dc) in dirs.items():
        r=(p[0]+dr,p[1]+dc); prev=(p[0]+2*dr,p[1]+2*dc)
        states.append(make_state(agent=p, mover=r, mover_prev=prev)); meta.append(('mover_approach',p,d))

X = np.array(states)
out = forward(X)
z = out - out.max(axis=1,keepdims=True)
P = np.exp(z); P = P/P.sum(axis=1,keepdims=True)

baseP = {p:P[i] for i,(t,p,d) in enumerate(meta) if t=='base'}

print("mean base probs (no-op,up,down,left,right):",
      np.round(np.mean([baseP[p] for p in positions],axis=0),3))

from collections import defaultdict
res = defaultdict(lambda: defaultdict(list))
for i,(typ,p,d) in enumerate(meta):
    if typ=='base': continue
    t=aidx[d]; o=aidx[opp[d]]
    net=(P[i,t]-P[i,o])-(baseP[p][t]-baseP[p][o])
    res[typ][d].append(net)

print("\nPaired net attraction = (P_toward-P_away)_obj - (P_toward-P_away)_base")
for typ in ['reward','obstacle','mover_stat','mover_approach']:
    allv=[]; line=f"{typ:15s}"
    for d in ['up','down','left','right']:
        v=np.array(res[typ][d]); allv+=list(v)
        line+=f" {d}:{v.mean():+.3f}"
    allv=np.array(allv); se=allv.std(ddof=1)/np.sqrt(len(allv))
    print(line+f" | NET {allv.mean():+.3f} +/- {se:.3f}")
